"Alex Ferguson era famoso por el «secador de pelo»: broncas a gritos a centímetros de la cara del jugador.":"Alex Ferguson war berühmt für den „Föhn“: lautstarke Standpauken wenige Zentimeter vor dem Gesicht des Spielers.",
"Alex Ferguson llegó al Manchester United en noviembre de 1986 y no ganó su primer título hasta la FA Cup de 1990. El club le mantuvo pese a las críticas y acabó ganando trece ligas.":"Alex Ferguson kam im November 1986 zu Manchester United und gewann seinen ersten Titel erst mit dem FA Cup 1990. Der Klub hielt trotz Kritik an ihm fest, und er gewann am Ende dreizehn Meisterschaften.",
