"Alguien lo graba. «El jugador que pasa de los niños».":"Jemand filmt es. „Der Spieler, dem Kinder egal sind.“",
"Alguien rescata un tuit tuyo de cuando tenías 14 años. Es una tontería, pero las redes arden.":"Jemand gräbt einen Tweet von dir aus, als du 14 warst. Es ist Unsinn, aber das Netz brennt.",
"Alguien sube una foto tuya con una copa a las 3 de la mañana. El club abre expediente.":"Jemand postet ein Foto von dir mit einem Drink um 3 Uhr morgens. Der Verein leitet ein Verfahren ein.",
