"Algunas piezas se desbloquean con fama, títulos o dinero.":"Manche Teile schaltest du mit Ruhm, Titeln oder Geld frei.",
"Algunas rojas no se las cree ni el árbitro que las sacó.":"An manche Rote Karten glaubt nicht mal der Schiri, der sie gezeigt hat.",
