"Algunos compañeros te apoyan en voz baja. El míster, no.":"Einige Mitspieler unterstützen dich leise. Der Trainer nicht.",
"Algunos lo ven como una provocación y la burla se alarga.":"Manche sehen es als Provokation, und der Spott geht weiter.",
"Algunos padres se quejan de que pagaron por verte y no estabas.":"Einige Eltern beschweren sich, dass sie bezahlt haben, um dich zu sehen, und du nicht da warst.",
"Algunos partidos en el estadio, otros en la ciudad deportiva. Un parche razonable.":"Einige Spiele im Stadion, andere auf dem Trainingsgelände. Ein vernünftiger Kompromiss.",
"Algunos pesos pesados se sienten humillados y se cierran en banda.":"Einige Führungsspieler fühlen sich gedemütigt und machen dicht.",
