"Cada cambio es un golpe de energía. Sois un equipo de 22.":"Jeder Wechsel ist ein Energieschub. Ihr seid ein Team aus 22.",
"Cada desventaja tiene su ventaja. Con menos dinero, tenemos más hambre. Y el hambre gana más partidos que el oro.":"Jeder Nachteil hat seinen Vorteil. Mit weniger Geld haben wir mehr Hunger. Und Hunger gewinnt mehr Spiele als Gold.",
"Cada día se nota más lo que vale {name}. Otro gol y van {goals}. ¡CRACK!":"Man sieht jeden Tag mehr, was {name} draufhat. Noch ein Tor, das macht {goals}. KÖNNER!",
"Cada día un reto. Pero sufrir es parte del trabajo. Quien no sufre no sabe lo que vale volver a jugar.":"Jeder Tag eine Herausforderung. Aber Leiden gehört zum Job. Wer nicht leidet, weiß nicht, was es wert ist, wieder zu spielen.",
"Cada etapa de tu mascota tiene su propio dibujo: cuando crezca, quizá tengas que volver a colocarlos.":"Jede Phase deines Haustiers hat ihr eigenes Bild: Wenn es wächst, musst du sie vielleicht neu platzieren.",
"Cada jugador rinde al 100 % en su posición.":"Jeder Spieler bringt auf seiner Position 100 % Leistung.",
"Cada mal partido se compara con las leyendas. La presión se nota.":"Jedes schwache Spiel wird mit den Legenden verglichen. Der Druck ist spürbar.",
"Cada ojeador te trae informes al empezar cada tramo. Con más estrellas, el potencial que ves es más fiable; con más viajes, encuentra más jugadores.":"Jeder Scout bringt dir zu Beginn jedes Abschnitts Berichte. Mehr Sterne = verlässlicheres Potenzial; mehr Reisen = mehr gefundene Spieler.",
"Cada partido es historia. Los jóvenes aprenden de ti.":"Jedes Spiel ist Geschichte. Die Jungen lernen von dir.",
"Cada partido peor que el anterior. ¿Qué estamos haciendo?":"Jedes Spiel schlechter als das davor. Was machen wir hier eigentlich?",
"Cada punto es un jugador con su dorsal y los colores de su equipo.":"Jeder Punkt ist ein Spieler mit Rückennummer und den Farben seines Teams.",
"Cada uno en su sitio":"Jeder auf seiner Position",
"Cada uno por su lado.":"Jeder geht seinen Weg.",
"Cada uno sabe lo que tiene que hacer. Ni euforia ni miedo.":"Jeder weiß, was er zu tun hat. Weder Euphorie noch Angst.",
"Cada vez más cerca del descenso. ¿Qué le dice al vestuario?":"Der Abstieg rückt immer näher. Was sagst du der Kabine?",
"Cada vez que creo que no pueden jugar peor… lo hacen. Impresionante 👏 (ironía)":"Jedes Mal, wenn ich denke, schlechter geht's nicht… geht's doch. Beeindruckend 👏 (Ironie)",
