"Cuando aparece una tarjeta de decisión, elige una opción: los números de colores te dicen qué ganas y qué pierdes antes de elegir.":"Wenn eine Entscheidungskarte erscheint, wähle eine Option: Die farbigen Zahlen zeigen dir vorher, was du gewinnst und was du verlierst.",
"Cuando el club te renueva y tu agente ya está pidiendo más dinero 🤑":"Wenn der Verein dir verlängert und dein Berater schon mehr Geld will 🤑",
"Cuando el comentarista dice 'esto está siendo un partido de ajedrez' y llevan 0 remates en 60 minutos ♟️":"Wenn der Kommentator sagt „das ist hier eine Schachpartie“ und es nach 60 Minuten 0 Torschüsse gibt ♟️",
"Cuando el {club} gana y te sientes tú el que ha metido el gol, papi 😎⚽":"Wenn {club} gewinnt und du dich fühlst, als hättest du selbst das Tor gemacht, Papi 😎⚽",
"Cuando ganas y todo el grupo de WhatsApp se llena de audios de 3 minutos 🗣️🗣️🗣️":"Wenn du gewinnst und die WhatsApp-Gruppe sich mit 3-Minuten-Sprachnachrichten füllt 🗣️🗣️🗣️",
"Cuando las gaviotas siguen al barco pesquero es porque creen que les van a tirar sardinas. Muchas gracias.":"Wenn die Möwen dem Fischkutter folgen, dann weil sie glauben, dass Sardinen ins Meer geworfen werden. Vielen Dank.",
"Cuando tu equipo juega mal pero ganas: 'Eso es lo importante' / Cuando tu equipo juega bien pero pierdes: 😭":"Wenn dein Team schlecht spielt, aber gewinnt: „Das ist das Wichtigste“ / Wenn dein Team gut spielt, aber verliert: 😭",
"Cuando uno pierde, todos pierden. Hoy el único responsable soy yo. Yo debí dar más.":"Wenn einer verliert, verlieren alle. Heute bin ich allein verantwortlich. Ich hätte mehr geben müssen.",
"Cuando {name} toca el balón, siento que todo va a salir bien ✨":"Wenn {name} am Ball ist, habe ich das Gefühl, dass alles gut wird ✨",
"Cuanto más difícil, mayor recompensa si lo cumples.":"Je schwerer, desto größer die Belohnung, wenn du es schaffst.",
"Cuanto más fuerte el vínculo, más te ayuda. Si no le dedicas tiempo, se debilita.":"Je stärker die Bindung, desto mehr hilft es dir. Wenn du dir keine Zeit nimmst, wird sie schwächer.",
"Cuanto más mejore al equipo, más caro será el traspaso y más alto el sueldo, siempre según tu presupuesto.":"Je mehr er das Team verbessert, desto teurer die Ablöse und desto höher das Gehalt, immer passend zu deinem Budget.",
