"Dije lo que pensaba. Si no le gusta, que me lo diga a la cara. Es como si fuera mi hermano, pero con menos paciencia.":"Ich habe gesagt, was ich denke. Wenn es ihm nicht passt, soll er es mir ins Gesicht sagen. Er ist wie ein Bruder für mich, nur mit weniger Geduld.",
"Dije lo que sentía. Yo no me escondo, ni de la prensa ni de nadie. Si me sancionan, lo acepto y punto.":"Ich habe gesagt, was ich gefühlt habe. Ich verstecke mich nicht, weder vor der Presse noch vor sonst wem. Wenn ich gesperrt werde, akzeptiere ich das, Punkt.",
