"El Olympique de Lyon ha ganado ocho Champions League femeninas, cinco seguidas entre 2016 y 2020, con una plantilla llena de estrellas.":"Olympique Lyon hat acht Champions-League-Titel der Frauen gewonnen, fünf davon in Folge zwischen 2016 und 2020, mit einem Kader voller Stars.",
