"Entrenar con el filial para coger ritmo":"Mit der zweiten Mannschaft trainieren, um in den Rhythmus zu kommen",
"Entrenar con él por tu cuenta":"Selbst mit ihm trainieren",
"Entrenar igual":"Trotzdem trainieren",
"Entrenar te despeja. Poco a poco vuelve la chispa.":"Training macht den Kopf frei. Langsam kehrt der Funke zurück.",
"Entrevista con tu pareja":"Interview mit deiner Partnerin",
"Entrevistas, marcas y redes: más seguidores y más fama cada tramo.":"Interviews, Marken und Social Media: mehr Follower und mehr Ruhm in jedem Abschnitt.",
"Enviar un burofax pidiendo salir":"Ein Einschreiben mit Wechselwunsch schicken",
"Enviar un informe a la federación":"Einen Bericht an den Verband schicken",
"Envíalos a una región: traerán jugadores de esa zona que encajan en tus necesidades.":"Schick sie in eine Region: Sie bringen Spieler aus diesem Gebiet, die zu deinem Bedarf passen.",
"Equilibrada":"Ausgewogen",
"Equilibrada es la opción segura si no sabes qué hacer.":"Ausgewogen ist die sichere Wahl, wenn du nicht weißt, was du tun sollst.",
"Equilibrado":"Ausgewogen",
"Equilibrio entre progresión y descanso.":"Gleichgewicht zwischen Entwicklung und Erholung.",
"Equipa todas tus ranuras con piezas Oro o superiores.":"Belege alle Plätze mit Teilen der Stufe Gold oder höher.",
