"Equipo {st}.":"Spielt {st}.",
"Equípate para sumar a tus atributos.":"Rüste dich aus, um deine Werte zu verbessern.",
"Era el cumpleaños de un amigo. Estuve un rato y me fui pronto. Si queréis las pruebas, enseño el ticket del Uber.":"Es war der Geburtstag eines Freundes. Ich war kurz da und bin früh gegangen. Wenn ihr Beweise wollt, zeige ich euch die Uber-Quittung.",
"Era el derbi. ¿Qué significa este resultado para la afición?":"Es war das Derby. Was bedeutet dieses Ergebnis für die Fans?",
"Era humo. Pierdes hasta el último euro.":"Alles heiße Luft. Du verlierst jeden einzelnen Euro.",
"Eredivisie":"Eredivisie",
"Eres agente libre: elige tu nuevo club":"Du bist vereinslos: Wähle deinen neuen Verein",
"Eres el capitán":"Du bist der Kapitän",
"Eres el dueño y el entrenador: nadie puede despedirte, pero el dinero y la plantilla dependen de tus resultados.":"Du bist Besitzer und Trainer: Niemand kann dich entlassen, aber Geld und Kader hängen von deinen Ergebnissen ab.",
"Eres el nuevo seleccionador: {nat}.":"Du bist der neue Nationaltrainer: {nat}.",
"Eres el presidente: el entrenador dirige los partidos. Elige uno que encaje con tu presupuesto.":"Du bist der Präsident: Der Trainer leitet die Spiele. Wähle einen, der zu deinem Budget passt.",
"Eres el presidente: necesitas un entrenador que dirija los partidos. Sin él, el equipo rinde bastante peor.":"Du bist der Präsident: Du brauchst einen Trainer für die Spiele. Ohne ihn spielt das Team deutlich schlechter.",
"Eritrea":"Eritrea",
"Erizo":"Igel",
"Es culpa mía, y solo mía. Una semana a oscuras para reflexionar. Que nadie más cargue con esto.":"Das ist meine Schuld, nur meine. Eine Woche im Dunkeln zum Nachdenken. Niemand sonst soll das tragen.",
"Es culpa mía. Cometí un error y costó el partido. Pido perdón a la afición y a mis compañeros. Lo asumo.":"Das ist meine Schuld. Ich habe einen Fehler gemacht und er hat uns das Spiel gekostet. Ich entschuldige mich bei den Fans und meinen Mitspielern. Ich stehe dazu.",
"Es culpa mía. Me responsabilizo de todo; los jugadores han dado lo que tenían.":"Das ist meine Schuld. Ich übernehme die volle Verantwortung; die Spieler haben alles gegeben, was sie hatten.",
"Es de todos: jugadores, cuerpo técnico, afición. Yo solo he puesto un granito.":"Er gehört allen: Spielern, Trainerteam, Fans. Ich habe nur ein Körnchen beigetragen.",
"Es el fútbol moderno. Con 30 cámaras no hay manera de decidir si es penalti. Con cero cámaras era más fácil.":"Das ist moderner Fußball. Mit 30 Kameras kann man nicht entscheiden, ob es Elfmeter ist. Mit null Kameras war es einfacher.",
"Es el fútbol, amigo. A veces la pelota entra y a veces el poste manda. Hoy, nos amó.":"Das ist Fußball, mein Freund. Mal geht der Ball rein, mal entscheidet der Pfosten. Heute hat er uns geliebt.",
"Es el resultado de mi peluquero, un genio. Y de la dieta de pasta, que me ha dejado sin ideas.":"Das ist das Werk meines Friseurs, ein Genie. Und der Nudeldiät, die mir die Ideen geraubt hat.",
"Es el sueño de este vestuario y vamos a pelearlo hasta el final.":"Das ist der Traum dieser Kabine, und dafür kämpfen wir bis zum Schluss.",
"Es el sueño de toda mi vida. Se lo dedico a mi familia.":"Das ist der Traum meines Lebens. Ich widme es meiner Familie.",
"Es el árbitro quien decide. Yo no puedo hacer nada. Hay que aceptar y seguir. La próxima, nosotros decidiremos.":"Der Schiri entscheidet. Ich kann nichts tun. Man muss es akzeptieren und weitermachen. Beim nächsten Mal entscheiden wir.",
"Es fútbol: hoy perdemos, mañana ganamos. No hay que hacer un drama.":"Das ist Fußball: Heute verlieren wir, morgen gewinnen wir. Kein Grund für ein Drama.",
"Es la mitad de mi trabajo. Un grito a tiempo vale más que una parada.":"Sie ist die Hälfte meiner Arbeit. Ein Schrei zur rechten Zeit ist mehr wert als eine Parade.",
"Es mentira. Lo que he pedido es que el hotel tenga mejor café. Eso sí lo he pedido, y con insistencia.":"Das ist gelogen. Ich habe gefordert, dass das Hotel besseren Kaffee hat. Das habe ich gefordert, und zwar mit Nachdruck.",
"Es nuestro mejor jugador y lo va a demostrar. Tiene toda mi confianza.":"Er ist unser bester Spieler, und das wird er zeigen. Er hat mein volles Vertrauen.",
"Es otro partido, aunque sé lo que significa. Vendrán a vernos 60 mil personas y no voy a defraudarlas.":"Es ist ein Spiel wie jedes andere, auch wenn ich weiß, was es bedeutet. 60.000 Leute kommen, und ich werde sie nicht enttäuschen.",
"Es parte del trabajo. Si no te insultan es que no importas. Y me insultaron mucho, así que algo importo.":"Das gehört zum Job. Wenn dich keiner beleidigt, bist du unwichtig. Und mich haben sie oft beleidigt – also bin ich wohl wichtig.",
"Es tu primera cena con la plantilla y la tradición manda: los nuevos tienen que subirse a una silla y cantar una canción.":"Es ist dein erstes Essen mit der Mannschaft und die Tradition verlangt: Neue müssen auf einen Stuhl steigen und ein Lied singen.",
"Es un maestro del 'mind games'. Que hable lo que quiera; yo me ocupo de entrenar a mi gente.":"Er ist ein Meister der 'mind games'. Soll er reden, so viel er will; ich kümmere mich ums Training meiner Leute.",
"Es un palo tremendo. Ya estamos pidiendo al club que busque a alguien. Como sea y cuando sea.":"Ein brutaler Schlag. Wir bitten den Verein schon, jemanden zu suchen. Egal wie und egal wann.",
"Es un problema, claro. Pero también es una oportunidad para los jóvenes. Los vais a ver, y os van a gustar.":"Ein Problem, klar. Aber auch eine Chance für die Jungen. Ihr werdet sie sehen, und sie werden euch gefallen.",
"Es una desventaja, claro. Pero a nosotros nadie nos regaló nunca nada. Por eso siempre seremos distintos.":"Natürlich ist das ein Nachteil. Aber uns hat nie jemand etwas geschenkt. Deshalb werden wir immer anders sein.",
"Es una final y las finales no se juegan, se ganan. No hay otra opción, y todos lo saben.":"Es ist ein Finale, und Finals spielt man nicht, man gewinnt sie. Es gibt keine andere Option, und alle wissen das.",
"Es una pérdida enorme, pero tenemos un plantel capaz de suplir a cualquiera. Los demás tendrán su oportunidad.":"Ein riesiger Verlust, aber wir haben einen Kader, der jeden ersetzen kann. Die anderen bekommen ihre Chance.",
"Escaparte sin permiso":"Ohne Erlaubnis abhauen",
"Escaparte una noche":"Eine Nacht verschwinden",
"Escarapela de campeón local":"Rosette Lokalmeister",
