"Escuchar ofertas (mercado cerrado)":"Angebote anhören (Transfermarkt geschlossen)",
"Escuchas a cada jugador. El ambiente se relaja.":"Du hörst jedem Spieler zu. Die Stimmung entspannt sich.",
"Escuchen lo que ha dicho {name}: «{quote}». Yo no sé qué piensan ustedes, pero a mí me parece digno de análisis.":"Hören Sie sich an, was {name} gesagt hat: „{quote}“. Ich weiß nicht, was Sie denken, aber ich finde, das verdient eine Analyse.",
