"Final de copa":"Pokalfinale",
"Final de la Champions de 2014 en Lisboa: Sergio Ramos empató de cabeza en el minuto 92:48 y el Real Madrid acabó ganando la Décima.":"Champions-League-Finale 2014 in Lissabon: Sergio Ramos glich in der 93. Minute (92:48) per Kopf aus und Real Madrid gewann am Ende die Décima.",
"Final de la Eurocopa 1976: Antonín Panenka picó así el penalti decisivo y dio el título a Checoslovaquia.":"Finale der Europameisterschaft 1976: Antonín Panenka lupfte so den entscheidenden Elfmeter und holte den Titel für die Tschechoslowakei.",
"Final de la Eurocopa 1976: Antonín Panenka picó así el último penalti y dio el título a Checoslovaquia.":"EM-Finale 1976: Antonín Panenka lupfte so den letzten Elfmeter und holte der Tschechoslowakei den Titel.",
"Final del Mundial 1994: Roberto Baggio mandó su penalti por encima del larguero y Brasil fue campeón.":"WM-Finale 1994: Roberto Baggio schoss seinen Elfmeter über die Latte und Brasilien wurde Weltmeister.",
"Final del Mundial 2006: Zidane respondió con un cabezazo a una provocación de Materazzi y se despidió del fútbol con una roja.":"WM-Finale 2006: Zidane antwortete auf eine Provokation von Materazzi mit einem Kopfstoß und verabschiedete sich mit einer Roten Karte vom Fußball.",
"Final del Mundial 2022: Emiliano «Dibu» Martínez desconcentró a los lanzadores de Francia y Argentina ganó la tanda.":"WM-Finale 2022: Emiliano „Dibu“ Martínez brachte die französischen Schützen aus der Konzentration und Argentinien gewann das Elfmeterschießen.",
