"HAT-TRICK de {name}. Esto es carta Héroe asegurada. Walkout incoming 🎆":"HATTRICK von {name}. Die Hero-Karte ist sicher. Walkout incoming 🎆",
"HUMILLACIÓN | El {opp} destroza al {club} ({score}) y deja una imagen preocupante.":"DEMÜTIGUNG | {opp} zerlegt {club} ({score}) und hinterlässt ein besorgniserregendes Bild.",
"Ha encontrado un palo. Muy orgulloso.":"Einen Stock gefunden. Sehr stolz.",
"Ha fichado un compañero que no habla ni una palabra del idioma del vestuario. El míster te pide que le hagas de traductor y guía los primeros meses.":"Ein neuer Mitspieler spricht kein Wort der Kabinensprache. Der Trainer bittet dich, in den ersten Monaten sein Übersetzer und Begleiter zu sein.",
"Ha ganado el derbi y ha celebrado delante de la grada rival. ¿Provocación?":"Du hast das Derby gewonnen und vor der gegnerischen Kurve gejubelt. Provokation?",
"Ha hecho otro truco":"Hat einen anderen Trick gemacht",
"Ha hecho un amigo nuevo.":"Hat einen neuen Freund gefunden.",
"Ha saltado en un charco.":"Ist in eine Pfütze gesprungen.",
"Ha tenido un rifirrafe con un compañero en el entrenamiento. ¿Qué pasó?":"Du bist im Training mit einem Mitspieler aneinandergeraten. Was war los?",
"Habitual":"Stammspieler",
"Hablar con el director deportivo":"Mit dem Sportdirektor reden",
"Hablar con el psicólogo del club (20 k€)":"Mit dem Vereinspsychologen sprechen (20 k€)",
"Hablar con el seleccionador":"Mit dem Nationaltrainer reden",
"Hablar con un profesional te cambia el chip. Vuelves a sonreír en los entrenos.":"Mit einem Profi zu reden, bringt dich auf andere Gedanken. Im Training lächelst du wieder.",
"Hablar con {name}":"Mit {name} reden",
"Hablar con él":"Mit ihm reden",
"Hablar con él (ya hablasteis)":"Mit ihm reden (ihr habt schon gesprochen)",
"Hablar con él el primer día":"Am ersten Tag mit ihm reden",
"Hablar de ello en redes al día siguiente":"Am nächsten Tag in den sozialen Medien darüber sprechen",
"Hablar de lo que supone para tu liga":"Darüber sprechen, was es für deine Liga bedeutet",
"Hablar de trabajo y humildad":"Von Arbeit und Demut sprechen",
"Hablar directamente con el jugador":"Direkt mit dem Spieler reden",
"Hablar en inglés":"Englisch sprechen",
"Hablar en nombre del grupo":"Für die Gruppe sprechen",
"Hablar solo de la renovación":"Nur über die Vertragsverlängerung reden",
"Hablar solo de trabajo":"Nur über Arbeit sprechen",
"Hablar solo del partido":"Nur über das Spiel reden",
"Hablarlo a solas":"Unter vier Augen reden",
"Hablarlo cara a cara con él":"Unter vier Augen mit ihm reden",
"Hablarlo con él en privado":"Unter vier Augen mit ihm reden",
"Hablarlo en privado":"Unter vier Augen sprechen",
"Hablarlo en privado con el presidente":"Privat mit dem Präsidenten reden",
"Hablaré con él cara a cara. Si de verdad no es feliz, buscaremos una solución que nos convenga a ambos.":"Ich rede von Angesicht zu Angesicht mit ihm. Wenn er wirklich nicht glücklich ist, finden wir eine Lösung, die für beide passt.",
"Hablaré con él en privado. Aquí en público solo digo que no representa los valores de este club.":"Ich rede unter vier Augen mit ihm. Hier öffentlich sage ich nur, dass er nicht die Werte dieses Vereins vertritt.",
"Hablaré del futuro cuando termine la temporada. Ahora mismo mi única obsesión es el siguiente partido.":"Über die Zukunft rede ich nach der Saison. Gerade ist meine einzige Obsession das nächste Spiel.",
"Hablas de futuro y de ilusión. Poco a poco la grada se anima.":"Du sprichst von Zukunft und Vorfreude. Nach und nach zieht die Kurve mit.",
"Hablas de futuro y de ingresos. La directiva está encantada.":"Du sprichst von Zukunft und Einnahmen. Der Vorstand ist begeistert.",
"Hablo sin parar con mis centrales. Si la defensa está bien colocada, yo apenas trabajo.":"Ich rede ununterbrochen mit meinen Innenverteidigern. Wenn die Abwehr gut steht, habe ich kaum Arbeit.",
"Hablé con ellos, les puse un vídeo de hace tres años y todo el mundo lloró. Ya veis, así de fácil.":"Ich habe mit ihnen geredet, ihnen ein Video von vor drei Jahren gezeigt, und alle haben geweint. Seht ihr, so einfach ist das.",
"Habrá tiempo cuando te retires.":"Dafür ist nach der Karriere noch Zeit.",
"Habéis ganado el derbi ante el {opp} ({gu}-{gt}). ¿Cómo se celebra algo así?":"Ihr habt das Derby gegen {opp} gewonnen ({gu}:{gt}). Wie feiert man so etwas?",
"Habéis perdido la final ante el {opp}. ¿Cómo se levanta uno de esto?":"Ihr habt das Finale gegen {opp} verloren. Wie steht man nach so etwas wieder auf?",
"Hace nada levantaste un título importante, pero tras una mala racha la directiva empieza a dudar de ti.":"Vor Kurzem hast du einen wichtigen Titel geholt, aber nach einer Negativserie fängt der Vorstand an, an dir zu zweifeln.",
"Hace tiempo que no le dedicas un rato a {pet}. Te está esperando en casa 🐾":"Du hast schon lange keine Zeit mehr mit {pet} verbracht. Es wartet zu Hause auf dich 🐾",
