"Hora":"Uhrzeit",
"Hora de cerrar el programa y aún no sé si el {club} juega bien o es que los demás juegan peor. Buenas noches. 🌙":"Zeit, die Sendung zu beenden, und ich weiß immer noch nicht, ob {club} gut spielt oder die anderen schlechter. Gute Nacht. 🌙",
"Hora del baño":"Badezeit",
"Horas antes de la gala del Balón de Oro te llega el soplo: no vas a ganar, quedarás {pos}. En el {club} proponen no viajar a París en señal de protesta.":"Stunden vor der Gala zum Ballon d'Or bekommst du den Tipp: Du gewinnst nicht, du wirst {pos}. Bei {club} schlagen sie vor, aus Protest nicht nach Paris zu reisen.",
"Horas de vídeo. Llegáis preparados.":"Stundenlang Videoanalyse. Ihr seid bestens vorbereitet.",
"Horas extra":"Sonderschichten",
"Horas y horas de coche. Llegas cansado y el míster no lo ve claro.":"Stunden um Stunden im Auto. Du kommst müde an, und der Trainer ist skeptisch.",
"Horas y horas de trabajo defensivo.":"Stunde um Stunde Defensivarbeit.",
