"Llega como cría y crece contigo temporada a temporada. Tienes {m}.":"Es kommt als Jungtier und wächst Saison für Saison mit dir. Du hast {m}.",
"Llega desde el {club} con rol de {role}.":"Kommt von {club} mit der Rolle {role}.",
"Llega el derbi contra el {rival}. Un amigo te ha preparado una camiseta interior con un mensaje para la afición rival, para enseñarla si marcas.":"Das Derby gegen {rival} steht an. Ein Freund hat dir ein Unterhemd mit einer Botschaft für die gegnerischen Fans gemacht, das du zeigen sollst, wenn du triffst.",
"Llega la primera derrota y alguien culpa al gato. Ridículo nacional.":"Die erste Niederlage kommt und jemand gibt der Katze die Schuld. Landesweite Blamage.",
"Llega la ventana internacional y tienes que cerrar la lista. Un veterano que lo ganó todo vuelve a estar en forma y un joven lleva semanas marcando en su club.":"Die Länderspielpause steht an und du musst den Kader festlegen. Ein Routinier, der alles gewonnen hat, ist wieder in Form, und ein Youngster trifft seit Wochen für seinen Verein.",
"Llega un preparador de porteros con ideas modernas: quiere que juegues más adelantado y con los pies, aunque eso cambie tu forma de parar.":"Ein Torwarttrainer mit modernen Ideen kommt: Du sollst weiter vor dem Tor stehen und mehr mit dem Fuß spielen, auch wenn das deine Art zu halten verändert.",
"Llega un veterano que les hace de hermano mayor.":"Ein Routinier kommt und wird für sie zum großen Bruder.",
"Llega una estrella al vestuario. Hay más calidad, pero hay que hacerle sitio.":"Ein Star kommt in die Kabine. Mehr Qualität, aber man muss ihm Platz machen.",
"Llega una oferta del {club} por {name}: {fee}.":"{club} bietet für {name}: {fee}.",
"Llega {name} al {club}. Les digo una cosa: este fichaje es de los que marcan una época. 🤍":"{name} kommt zu {club}. Ich sage Ihnen eines: Dieser Transfer ist einer, der eine Ära prägt. 🤍",
"Llega {name} al {club}. Veamos qué da. Que nos quede bien claro que no es un fichaje estrella.":"{name} kommt zu {club}. Mal sehen, was er bringt. Eins ist klar: Ein Startransfer ist das nicht.",
"Llega {name}. Que nos explique el plan y a trabajar. Calma, que esto es largo.":"{name} kommt. Soll uns den Plan erklären und dann ran an die Arbeit. Ruhe, das wird ein langer Weg.",
"Llegan dos veteranos que saben lo que es ganar. El vestuario se crece.":"Zwei Routiniers kommen, die wissen, wie man gewinnt. Die Kabine wächst über sich hinaus.",
"Llegan los juveniles":"Die Junioren kommen",
