"Llegarán con menos rodaje juntos, pero conocerás a todos.":"Sie haben weniger Spielpraxis zusammen, aber du lernst alle kennen.",
"Llegarán ofertas en el próximo mercado":"Zum nächsten Transferfenster kommen Angebote",
"Llegas a la pretemporada como un tiro.":"Du kommst topfit in die Vorbereitung.",
"Llegas a los postres, con el resultado en la boca. Tu hermano lo agradece.":"Du kommst zum Nachtisch, mit dem Ergebnis im Gepäck. Dein Bruder freut sich.",
"Llegas a los postres, pero llegas.":"Du kommst zum Nachtisch, aber du kommst.",
"Llegas a tiempo para ver nacer a tu hijo. Nada en el mundo vale más.":"Du kommst rechtzeitig, um die Geburt deines Kindes zu erleben. Nichts auf der Welt ist mehr wert.",
"Llegas a tiempo, con la camiseta aún puesta. Una historia para contarle.":"Du kommst rechtzeitig, noch im Trikot. Eine Geschichte für später.",
"Llegas a tu nuevo club con fama de exagerar las faltas y la prensa local te ha recibido con burlas. Si marcas en el debut, ¿cómo lo celebras?":"Du kommst mit dem Ruf zu deinem neuen Verein, Fouls zu übertreiben, und die Lokalpresse hat dich mit Spott empfangen. Wenn du beim Debüt triffst: Wie jubelst du?",
"Llegas a un vestuario con dos estrellas veteranas, {name1} y {name2}, que cobran una fortuna y ya no corren como antes. La cantera aprieta desde abajo.":"Du übernimmst eine Kabine mit zwei erfahrenen Stars, {name1} und {name2}, die ein Vermögen verdienen und nicht mehr so laufen wie früher. Die Jugend drängt von unten nach.",
"Llegas al entreno como una estrella de cine.":"Du kommst zum Training wie ein Filmstar.",
"Llegas cargado a la concentración. El cuerpo técnico te deja elegir: jugar el amistoso o descansar para volver fresco a tu club.":"Du kommst ausgelaugt ins Lager. Das Trainerteam lässt dich wählen: das Testspiel bestreiten oder ausruhen und frisch zu deinem Verein zurückkehren.",
"Llegas como {role} a {lg}.":"Du kommst als {role} in {lg} an.",
"Llegas con {fit} de físico y {form} de forma.":"Du kommst mit {fit} Fitness und {form} Form.",
"Llegas fresco al inicio de liga, aunque el míster esperaba más.":"Du bist frisch zum Ligastart, auch wenn der Trainer mehr erwartet hatte.",
"Llegas fresco, aunque al míster le gusta ver ambición":"Du kommst frisch an, aber der Trainer will Ehrgeiz sehen",
"Llegas justo de hora al entrenamiento y un niño con tu camiseta lleva una hora esperándote bajo la lluvia.":"Du kommst auf den letzten Drücker zum Training und ein Junge in deinem Trikot wartet schon seit einer Stunde im Regen auf dich.",
"Llegas la víspera y duermes en tu cama.":"Du kommst am Vorabend an und schläfst im eigenen Bett.",
"Llegas tarde por diez minutos. No te lo perdonas.":"Du kommst zehn Minuten zu spät. Das verzeihst du dir nicht.",
"Llegas tarde y te cae una multa, pero mereció la pena.":"Du kommst zu spät und kassierst eine Geldstrafe, aber es hat sich gelohnt.",
"Llegas tarde: roja directa y falta peligrosa.":"Du kommst zu spät: glatt Rot und gefährlicher Freistoß.",
"Llegas un instante tarde.":"Du kommst einen Moment zu spät.",
"Llegáis descansados. El director financiero no tanto.":"Ihr kommt ausgeruht an. Der Finanzchef weniger.",
"Llegáis destrozados y se nota desde el primer minuto.":"Ihr kommt völlig platt an und das merkt man ab der ersten Minute.",
"Llegáis por la derecha: {a} pone el balón al área.":"Ihr kommt über rechts: {a} bringt den Ball in den Strafraum.",
