"Mal partido, sí. Pero un tropiezo no borra nada. Se volverá, como siempre se vuelve. 🤍":"Schlechtes Spiel, ja. Aber ein Ausrutscher löscht nichts aus. Man kommt zurück, wie man immer zurückkommt. 🤍",
