"Mirarla sin prisas te baja las pulsaciones.":"Ihm in Ruhe zuzusehen senkt deinen Puls.",
"Miro la cadera del lanzador hasta el último segundo. Y aguanto, aguanto…":"Ich schaue bis zur letzten Sekunde auf die Hüfte des Schützen. Und warte, warte…",
