"Más":"Mehr",
"Más asistencias en una temporada":"Meiste Vorlagen in einer Saison",
"Más ataque":"Mehr Offensive",
"Más baratas llenan el estadio y contentan a la afición; más caras dan más dinero por entrada, pero vacían la grada.":"Günstige Tickets füllen das Stadion und freuen die Fans; teure bringen mehr pro Ticket, leeren aber die Ränge.",
"Más cansancio y más molestias. La enfermería sigue llena.":"Mehr Müdigkeit, mehr Wehwehchen. Die Verletztenliste bleibt lang.",
"Más clubes se interesarán por ti en el próximo mercado. En el vestuario no gusta.":"Im nächsten Transferfenster werden sich mehr Klubs für dich interessieren. In der Kabine kommt das nicht gut an.",
"Más confianza del míster y más forma, a costa de cansancio.":"Mehr Vertrauen des Trainers und bessere Form, auf Kosten der Fitness.",
"Más de una bandera":"Mehr als eine Flagge",
"Más decoración en la tienda.":"Mehr Deko im Shop.",
"Más desborde y asistencias.":"Mehr Dribblings und Vorlagen.",
"Más descanso y trabajo específico. Notas el cambio en pocas semanas.":"Mehr Ruhe und gezieltes Training. Nach wenigen Wochen merkst du den Unterschied.",
"Más dinero hoy, menos margen salarial mañana.":"Heute mehr Geld, morgen weniger Gehaltsspielraum.",
"Más experiencia sobre el campo, pero los jóvenes se sienten traicionados.":"Mehr Erfahrung auf dem Platz, aber die Jungen fühlen sich verraten.",
"Más goles a favor":"Meiste Tore",
"Más goles en una temporada":"Meiste Tore in einer Saison",
"Más goles por partido.":"Mehr Tore pro Spiel.",
"Más grande":"Größer",
"Más juguetes":"Mehr Spielzeug",
"Más ocasiones a favor, algo más expuesto.":"Mehr Chancen für dich, etwas anfälliger hinten.",
"Más ofertas en el próximo mercado":"Mehr Angebote im nächsten Transferfenster",
"Más ofertas y mejores sueldos. Se queda el 10 %.":"Mehr Angebote und bessere Gehälter. Sie behalten 10 %.",
"Más ofertas · comisión del 10 %":"Mehr Angebote · 10 % Provision",
"Más ojos y más datos para decidir mejor.":"Mehr Augen und mehr Daten für bessere Entscheidungen.",
"Más opciones de ganar, a costa de algo de físico":"Bessere Siegchancen, kostet aber etwas Fitness",
"Más opciones de marcar y de convencer al míster, pero acabas fundido":"Mehr Chancen auf Tore und den Trainer zu überzeugen, aber du bist danach platt",
"Más pequeño":"Kleiner",
"Más progresión":"Mehr Entwicklung",
"Más puntos":"Meiste Punkte",
"Más que leyenda":"Mehr als eine Legende",
"Más química y un plus de nivel en los dos primeros tramos.":"Mehr Chemie und ein Leistungsplus in den ersten beiden Abschnitten.",
"Más recuperación y menos lesiones.":"Mehr Erholung und weniger Verletzungen.",
"Más regularidad y moral bajo presión.":"Mehr Konstanz und Nervenstärke unter Druck.",
"Más rica y nutritiva. Cinco raciones.":"Leckerer und nahrhafter. Fünf Portionen.",
"Más rotación descansa a los cansados en los partidos menores; en los grandes siempre juegan los mejores. Los cambios salen del banquillo.":"Mehr Rotation lässt müde Spieler in weniger wichtigen Spielen pausieren; in den großen Spielen spielen immer die Besten. Die Wechsel kommen von der Bank.",
"Más semanas de baja, recuperación completa.":"Mehr Wochen Pause, vollständige Genesung.",
"Más tarde":"Später",
"Más trabajo y menos lamentos":"Mehr Arbeit, weniger Jammern",
"Más títulos":"Meiste Titel",
"Máxima":"Maximal",
"Máxima concentración, pero el grupo puede agobiarse.":"Maximale Konzentration, aber die Gruppe kann sich eingeengt fühlen.",
"Máximo 26 convocados":"Maximal 26 Nominierte",
"Máximo asistente de {lg} ({n})":"Bester Vorlagengeber in {lg} ({n})",
"Máximo goleador":"Torschützenkönig",
"Máximo goleador de {lg} ({n} goles)":"Torschützenkönig in {lg} ({n} Tore)",
"Médico":"Medizin",
"Mérito de los guantes nuevos. Que les suban el sueldo a ellos.":"Das liegt an den neuen Handschuhen. Die sollen eine Gehaltserhöhung bekommen.",
"Mérito del portero y de los de atrás, pero también de los de arriba, que presionan como nadie.":"Verdienst des Torwarts und der Hintermannschaft, aber auch der Offensive, die presst wie keine andere.",
"México":"Mexiko",
