"Os abrís y os pillan a la contra. Ahora pitan más.":"Ihr macht auf und werdet ausgekontert. Jetzt pfeifen sie noch lauter.",
"Os atascáis en liga con tanto cambio y la prensa se pregunta qué pasa.":"Bei so vielen Wechseln stockt es in der Liga, und die Presse fragt, was los ist.",
"Os castigan cada espacio. Una goleada que escuece.":"Sie bestrafen jede Lücke. Eine Klatsche, die wehtut.",
"Os centráis en la liga. La asociación lo entiende, aunque no del todo.":"Ihr konzentriert euch auf die Liga. Die Organisation hat Verständnis, wenn auch nicht ganz.",
"Os dais la mano en el vestuario. Aquí no ha pasado nada.":"Ihr gebt euch in der Kabine die Hand. Alles halb so wild.",
"Os decís las cosas a la cara y salís reforzados.":"Ihr sagt euch die Wahrheit ins Gesicht und geht gestärkt daraus hervor.",
"Os decís las cosas a la cara. Te promete minutos pronto.":"Ihr sagt euch die Dinge ins Gesicht. Er verspricht dir bald Einsatzzeit.",
"Os decís las verdades y salís con un plan común.":"Ihr sagt euch die Meinung und geht mit einem gemeinsamen Plan raus.",
"Os encierran y llega el empate en un balón parado.":"Ihr werdet eingeschnürt und der Ausgleich fällt nach einem ruhenden Ball.",
"Os entendéis: competiréis, pero sin malos rollos.":"Ihr versteht euch: Ihr konkurriert, aber ohne böses Blut.",
"Os escuchan con una sonrisa y no cambia nada.":"Man hört euch lächelnd zu, und nichts ändert sich.",
"Os han goleado sin piedad y la prensa ya da la eliminatoria por perdida. En la rueda de prensa te preguntan si queda alguna esperanza.":"Ihr wurdet gnadenlos abgeschossen und die Presse hält das Duell schon für verloren. Auf der Pressekonferenz fragt man dich, ob es noch Hoffnung gibt.",
"Os lo avisé: {club} está para enmarcar. Pero en un cuadro triste 😂":"Ich hab's euch gesagt: {club} ist reif fürs Museum. Aber für ein trauriges Gemälde 😂",
"Os lo contaba hace semanas: {name} ya es del {club}. Firma hasta {year}. Cerrado. 🔵🔴":"Ich hab's euch vor Wochen erzählt: {name} ist jetzt bei {club}. Vertrag bis {year}. Erledigt. 🔵🔴",
"Os lo dije. LO DIJE. Y todavía hay gente que defiende esto 🤷":"Ich hab's euch gesagt. ICH HAB'S GESAGT. Und es gibt immer noch Leute, die das verteidigen 🤷",
"Os mudáis a un campo pequeño. La plantilla se siente de segunda.":"Ihr zieht auf einen kleinen Platz um. Die Mannschaft fühlt sich zweitklassig.",
"Os pasan por encima con uno más.":"Der Gegner überrollt euch in Überzahl.",
"Os pillan a la contra con el equipo partido.":"Ihr werdet bei einem Konter erwischt, die Mannschaft ist auseinandergerissen.",
"Os pillan a la contra: empate.":"Ihr werdet ausgekontert: Ausgleich.",
"Os quedáis con diez":"Ihr seid nur noch zu zehnt",
"Os quedáis sin torneo y parte de la prensa os culpa.":"Ihr verpasst das Turnier, und ein Teil der Presse gibt euch die Schuld.",
"Otra derrota ante un rival directo. ¿Es el momento de hacer cambios?":"Wieder eine Niederlage gegen einen direkten Konkurrenten. Ist es Zeit für Veränderungen?",
"Otra derrota dolorosa con tu selección y otra lluvia de críticas. En caliente, sientes que no quieres volver a ponerte esa camiseta.":"Wieder eine bittere Niederlage mit deiner Nationalmannschaft und wieder ein Hagel an Kritik. Im ersten Frust spürst du, dass du dieses Trikot nie wieder anziehen willst.",
