"Prefieres liderar con el ejemplo sin brazalete.":"Du gehst lieber mit gutem Beispiel voran, auch ohne Binde.",
"Prefieres no correr. El club toma nota de tu paciencia.":"Du willst nichts überstürzen. Der Verein registriert deine Geduld.",
"Prefieres no mentir. La grada se queda con la duda.":"Du willst lieber nicht lügen. Die Fans bleiben im Ungewissen.",
"Prefieres no mezclar. Sigues a lo tuyo.":"Du trennst lieber. Du bleibst bei dir.",
"Prefieres que hable el campo. Algunos fans se sienten solos.":"Du lässt lieber den Platz sprechen. Manche Fans fühlen sich allein gelassen.",
"Prefieres que hable tu fútbol.":"Du lässt lieber deinen Fußball sprechen.",
"Prefieres seguir en tu club, cerca de los tuyos. El club te lo agradece.":"Du bleibst lieber bei deinem Verein, nah bei deinen Liebsten. Der Verein weiß das zu schätzen.",
"Prefieres un año más con los chavales.":"Du bleibst lieber noch ein Jahr bei den Jungs.",
"Prefiero no hablar. Cualquier cosa que diga me costará una multa y mi cuenta corriente no está para bromas.":"Ich sage lieber nichts. Alles, was ich sage, kostet mich eine Geldstrafe, und mein Konto versteht da keinen Spaß.",
"Prefiero que hablen mis paradas.":"Ich lasse lieber meine Paraden sprechen.",
"Prefiero que me recuerden por mi nombre y por lo que gane.":"Ich will lieber für meinen Namen und meine Titel in Erinnerung bleiben.",
