"Pregúnteselo a él. Yo salí a disfrutar y a mover el balón. Lo demás, que lo arreglen los de arriba.":"Frag ihn selbst. Ich bin rausgegangen, um Spaß zu haben und den Ball laufen zu lassen. Den Rest sollen die da oben regeln.",
