"Quedarte y pelear":"Bleiben und kämpfen",
"Quedas segundo. Algunos critican tanta campaña.":"Du wirst Zweiter. Manche kritisieren die viele Werbung.",
"Quien quiera ganarnos, que venga preparado. Hoy no somos un rival cómodo.":"Wer uns schlagen will, muss gut vorbereitet kommen. Wir sind gerade kein bequemer Gegner.",
"Quiere esperar a ver qué otras ofertas le llegan.":"Er will abwarten, welche anderen Angebote reinkommen.",
"Quiere irse":"Er will weg",
"Quiere jugar contigo":"Will mit dir spielen",
"Quiere mimos":"Will Streicheleinheiten",
"Quiere más minutos":"Will mehr Spielzeit",
"Quiere presionar hacia su propia grada en el primer tiempo.":"Sie wollen in der ersten Halbzeit in Richtung ihrer eigenen Fans pressen.",
"Quiere que su bloque pueda salir en contra hacia su banquillo.":"Ihr Block soll in Richtung der eigenen Bank kontern können.",
"Quiere una cláusula de salida":"Er will eine Ausstiegsklausel",
"Quieren a tu segundo":"Sie wollen deinen Co-Trainer",
"Quieres demasiado y pierdes balones tontos.":"Du willst zu viel und verlierst dumme Bälle.",
"Quieres implantar una idea nueva: línea defensiva adelantada, presión alta y todos defendiendo en zona. Algunos veteranos se miran con escepticismo: «¿Y este quién se cree?».":"Du willst eine neue Idee einführen: hohe Abwehrlinie, Hochpressing und alle in Raumdeckung. Einige Routiniers schauen sich skeptisch an: „Wer glaubt der eigentlich, wer er ist?“",
"Quieres salir":"Du willst weg",
"Quiero marcar y celebrarlo delante de su afición. ¿Eso es malo? Es para lo que me pagan, y me pagan bien.":"Ich will treffen und vor ihren Fans jubeln. Ist das schlimm? Dafür werde ich bezahlt, und zwar gut.",
"Quiero un equipo competitivo. Y no estoy dispuesto a mentir: lo que tenemos no basta para pelear por todo.":"Ich will eine konkurrenzfähige Mannschaft. Und ich werde nicht lügen: Was wir haben, reicht nicht, um um alles zu kämpfen.",
"Quinto lanzador: {name}":"Fünfter Schütze: {name}",
"Quita emoción, quita rapidez y quita goles. Y ahora, además, quita sentido común. Pero es una opinión personal.":"Er nimmt Emotion, Tempo und Tore. Und jetzt auch noch den gesunden Menschenverstand. Aber das ist meine persönliche Meinung.",
"Quitar":"Entfernen",
"Quitar de la lista de venta":"Von der Verkaufsliste nehmen",
"Quitar jugador":"Spieler entfernen",
"Quitarle el brazalete":"Ihm die Binde abnehmen",
"Quitarte la camiseta y correr":"Trikot ausziehen und losrennen",
"Quizá me he pasado. Daré más continuidad al once.":"Vielleicht habe ich übertrieben. Ich werde der Startelf mehr Kontinuität geben.",
"Quién entra":"Wer kommt rein",
"Quién sale":"Wer geht raus",
"Qué datos guarda":"Welche Daten gespeichert werden",
"Qué dolor… estaba ganado. Estas cosas nos pasan solo a nosotros 😩":"Wie bitter… das war schon gewonnen. So was passiert nur uns 😩",
"Qué envidia ver cómo anima el {club}. Nosotros con la peor grada en años 😔":"Wie neidisch, wie {club} angefeuert wird. Wir haben die schlechteste Kurve seit Jahren 😔",
"Qué grande el {club}, {score}. Así se juega, máquinas 🤙":"Wie stark ist {club}, {score}. So wird gespielt, Maschinen 🤙",
"Qué mala suerte tiene el {opp}… ¡Esto no le pasa a nadie! 😅 (con respeto, eh)":"Was für ein Pech für {opp}… So was passiert sonst keinem! 😅 (bei allem Respekt)",
"Qué noche, qué equipo, qué locura. A disfrutar, pero mañana a currar 😄":"Was für eine Nacht, was für ein Team, was für ein Wahnsinn. Genießen – aber morgen wird wieder malocht 😄",
"Qué paliza, madre mía. {score}. Vamos a guardar el vídeo para los nietos 📹":"Was für eine Packung, meine Güte. {score}. Das Video heben wir für die Enkel auf 📹",
"Qué pena me dan los del {club}. Bueno, no tanto 😜":"Die {club}-Fans tun mir so leid. Na ja, nicht so sehr 😜",
"Qué suerte tiene este chico. Otro gol al {opp}… 🫤":"Was für ein Glück dieser Typ hat. Wieder ein Tor gegen {opp}… 🫤",
"Química":"Chemie",
"RD Congo":"DR Kongo",
"REMONTADA | El {club} da la vuelta al partido ante el {opp} ({score}).":"COMEBACK | {club} dreht das Spiel gegen {opp} ({score}).",
"REMONTADA ÉPICA. Qué final, qué locura. Chicos, ¿quién necesita series con esto?":"EPISCHES COMEBACK. Was für ein Finale, was für ein Wahnsinn. Leute, wer braucht da noch Serien?",
