"Reaccionando a la victoria del {club} ({score}) en el vídeo de hoy. Spoiler: me volví loco 🎬":"Im heutigen Video reagiere ich auf den Sieg von {club} ({score}). Spoiler: Ich bin ausgerastet 🎬",
