"Recaes y lo arrastras dos semanas.":"Du erleidest einen Rückfall und schleppst es zwei Wochen mit dir herum.",
"Recambio con proyección":"Ersatz mit Zukunft",
"Recargas cuerpo y mente, aunque vuelves con un par de kilos de más.":"Du lädst Körper und Geist auf, kommst aber mit ein paar Kilo zu viel zurück.",
"Recargas pilas, pero tanto viaje cansa.":"Du tankst Energie, aber das viele Reisen schlaucht.",
