"Recibes un premio importante y, sobre el escenario, el presentador te hace una pregunta humillante que nada tiene que ver con el fútbol.":"Du erhältst eine wichtige Auszeichnung, und auf der Bühne stellt dir der Moderator eine demütigende Frage, die nichts mit Fußball zu tun hat.",
