"Recortas y disparas con el alma. ¡GOL! El estadio se viene abajo.":"Du legst dir den Ball vor und schießt mit voller Wucht. TOR! Das Stadion bebt.",
"Recorte y disparo":"Ablegen und schießen",
"Recta":"Gerade",
