"Recupera energías":"Tankt Energie",
"Recuperación":"Regeneration",
"Recuperan antes entre partidos y se lesionan menos.":"Erholen sich zwischen den Spielen schneller und verletzen sich seltener.",
"Recuperan más y se lesionan menos, pero progresan algo menos.":"Sie erholen sich besser und verletzen sich seltener, entwickeln sich aber etwas langsamer.",
"Recuperas en tu campo y ves a la portera rival casi en el centro del campo. Tienes la jugada y apenas un segundo para decidir.":"Du eroberst den Ball in der eigenen Hälfte und siehst die gegnerische Torhüterin fast an der Mittellinie. Du hast die Chance und kaum eine Sekunde zum Entscheiden.",
"Recuperas la cuenta en horas y explicas lo ocurrido.":"Du hast den Account in wenigen Stunden zurück und erklärst, was passiert ist.",
