"Sin club":"Ohne Verein",
"Sin comentarios. Si cada vez que perdemos preguntan por el vestuario, nos quedamos sin vestuario.":"Kein Kommentar. Wenn ihr nach jeder Niederlage nach der Kabine fragt, haben wir bald keine Kabine mehr.",
"Sin comisiones, pero menos puertas abiertas.":"Keine Provision, aber weniger offene Türen.",
"Sin comisión · menos ofertas":"Keine Provision · weniger Angebote",
"Sin consecuencias en la carrera. Cada acierto te hace un poco mejor (con un tope por temporada).":"Ohne Folgen für die Karriere. Jeder Treffer macht dich etwas besser (mit Limit pro Saison).",
"Sin contratos ni marcas. Los niños lo copian en el patio y a ti te vale.":"Keine Verträge, keine Marken. Die Kids machen sie auf dem Schulhof nach, und dir reicht das.",
"Sin convocatorias hasta la próxima temporada":"Keine Nominierungen bis zur nächsten Saison",
"Sin dramas. Media plantilla nueva el lunes.":"Kein Drama. Am Montag eine halbe neue Mannschaft.",
"Sin dramas. Nadie se entera.":"Ohne Drama. Niemand bekommt es mit.",
"Sin equipo":"Vereinslos",
"Sin equipo no hay mercado.":"Ohne Team gibt es keinen Transfermarkt.",
"Sin familia por ahora":"Vorerst ohne Familie",
"Sin fondo":"Kein Hintergrund",
"Sin forzar: lo normal en pretemporada":"Ohne zu forcieren: normale Vorbereitung",
"Sin fuerzas. Te cambian al descanso y tardas días en recuperarte.":"Kraftlos. Du wirst zur Halbzeit ausgewechselt und brauchst Tage, um dich zu erholen.",
"Sin lesionados.":"Keine Verletzten.",
"Sin pareja":"Ohne Partner",
"Sin partido, pero con tiempo para trabajar la táctica.":"Kein Spiel, aber Zeit für Taktik.",
"Sin pelo":"Glatze",
"Sin pelos en la lengua":"Kein Blatt vor dem Mund",
"Sin plan específico.":"Kein besonderer Plan.",
"Sin presión, el gol llega solo.":"Ohne Druck fällt das Tor von selbst.",
"Sin presupuesto":"Kein Budget",
"Sin prisa, pero sin pausa.":"Ohne Hast, aber ohne Pause.",
"Sin prisa.":"Keine Eile.",
"Sin referencia":"Ohne Bezugspunkt",
"Sin renovar: en verano serás libre":"Keine Verlängerung: Im Sommer bist du frei",
"Sin rotación":"Flatterball",
"Sin su estrella":"Ohne seinen Star",
"Sin suplentes":"Keine Ersatzspieler",
"Sin titulares.":"Keine Schlagzeilen.",
"Sin títulos como jugador.":"Keine Titel als Spieler.",
"Sin viajes":"Keine Reisen",
"Sinceramente, ellos tienen más plantilla. Pero soñar es gratis.":"Ehrlich gesagt haben sie den besseren Kader. Aber träumen kostet nichts.",
"Singapur":"Singapur",
"Siria":"Syrien",
"Sistema":"System",
"Siuuu. Eso es lo que siento. Y que alguien me traiga un trofeo, que hoy me lo he ganado.":"Siuuu. Das fühle ich. Und jemand soll mir eine Trophäe bringen, die habe ich mir heute verdient.",
"Sky Sportz understands {to} are preparing a bid for {name}. Talks expected this week.":"Sky Sportz understands {to} are preparing a bid for {name}. Talks expected this week.",
"Slalom hasta el área":"Slalom bis in den Strafraum",
"Sobre la línea de gol":"Auf der Torlinie",
"Sobrecarga muscular":"Muskuläre Überlastung",
"Sois segundos, a {gap} del {rival}, con {left} por jugar. ¿Os veis campeones?":"Ihr seid Zweiter, {gap} hinter {rival}, und noch {left} zu spielen. Seht ihr euch als Meister?",
"Sois {pos}º, a {gap} de los puestos europeos que marca el {rival}. ¿Llegaréis?":"Ihr seid {pos}., {gap} hinter {rival} auf dem letzten Europapokalplatz. Schafft ihr das noch?",
"Sois {pos}º, a {gap} del ascenso que ahora tiene el {rival}. ¿Llegaréis?":"Ihr seid {pos}., {gap} hinter {rival} auf dem Aufstiegsplatz. Schafft ihr das noch?",
"Solo cantera":"Nur Nachwuchs",
"Solo con el mercado abierto":"Nur bei offenem Transferfenster",
"Solo cuando se gane":"Nur nach Siegen",
"Solo directos ocasionales":"Nur gelegentliche Streams",
"Solo presidente":"Nur Präsident",
"Solo se configura una vez. Después, la familia crece (o no) según tus decisiones.":"Wird nur einmal eingerichtet. Danach wächst die Familie (oder nicht), je nach deinen Entscheidungen.",
"Solo se va quien yo quiero que se vaya. Y {player} es un jugador que siempre querré tener en mi equipo.":"Hier geht nur, wen ich gehen lassen will. Und {player} ist ein Spieler, den ich immer in meinem Team haben will.",
"Solo {gap} os separan del descenso. ¿Os preocupa mirar hacia abajo?":"Nur {gap} Vorsprung auf die Abstiegszone. Macht euch der Blick nach unten Sorgen?",
"Soltar lo que llevas dentro en directo":"Live alles rauslassen",
"Somalia":"Somalia",
"Sombrero de copa":"Zylinder",
"Somos un equipo intenso. Prefiero pasarme que quedarme corto.":"Wir sind ein intensives Team. Lieber zu viel als zu wenig.",
"Somos una familia. Si alguien tiene un problema, todos lo tenemos. Esa es la clave, y nunca la cambiaremos.":"Wir sind eine Familie. Wenn einer ein Problem hat, haben wir es alle. Das ist der Schlüssel, und das werden wir nie ändern.",
"Son diez días juntos en la ciudad deportiva de la federación. Algunos jugadores echan de menos a su familia.":"Zehn Tage zusammen im Trainingszentrum des Verbands. Einige Spieler vermissen ihre Familie.",
"Son favoritos, sin duda. Nosotros intentaremos ponérselo difícil.":"Sie sind ohne Zweifel Favorit. Wir werden es ihnen schwer machen.",
"Son partidos para los que he vivido. Me gusta estar donde otros no se atreven a pisar. Y mañana pisaré fuerte.":"Für solche Spiele habe ich gelebt. Ich bin gern dort, wo andere sich nicht hintrauen. Und morgen trete ich kräftig auf.",
"Son profesionales y responden aunque vayan justos.":"Sie sind Profis und liefern, auch wenn sie am Limit sind.",
"Son tuyos para siempre: se guardan en este dispositivo y cuentan los de todas tus partidas.":"Sie gehören dir für immer: Sie werden auf diesem Gerät gespeichert und zählen aus allen deinen Spielen.",
"Sonidos de la mascota":"Haustier-Geräusche",
"Sonreír y quitar presión":"Lächeln und Druck rausnehmen",
"Sonríes y hablas solo de tu equipo.":"Du lächelst und sprichst nur über dein Team.",
"Soplas las velas y te vas.":"Du pustest die Kerzen aus und gehst.",
"Sorteo de la fase de grupos":"Auslosung der Gruppenphase",
"Sorteo de la fase de liga":"Auslosung der Ligaphase",
"Sorteo de {comp}: {team} y {opp}. Esto va a estar muy reñido 👀":"Auslosung {comp}: {team} gegen {opp}. Das wird richtig eng 👀",
"Sorteo de {round}":"Auslosung: {round}",
"Sorteo en directo":"Auslosung live",
"Sorteo: empieza a lanzar el {team}.":"Losentscheid: {team} beginnt.",
"Sospechas de todos y el ambiente se envenena.":"Du verdächtigst alle und die Stimmung wird vergiftet.",
"Soy del club hasta que la lesión me deje o hasta que ellos me echen. Mientras tanto, a trabajar con la pierna mala.":"Ich gehöre zum Verein, bis die Verletzung mich lässt oder bis sie mich rauswerfen. Bis dahin wird mit dem kaputten Bein gearbeitet.",
"Soy el primero en asumirlo. Tengo que sacar paradas que ahora no saco.":"Ich bin der Erste, der das zugibt. Ich muss Paraden zeigen, die mir gerade nicht gelingen.",
"Soy el que más trabaja de este vestuario. No lo digo yo, lo dice el entrenador. Pregúntenle.":"Ich bin der, der in dieser Kabine am meisten arbeitet. Das sage nicht ich, das sagt der Trainer. Fragt ihn.",
"Soy entrenador. Tengo contrato, pero mañana puedo estar en la calle. Así es esto y no me asusta.":"Ich bin Trainer. Ich habe einen Vertrag, aber morgen kann ich auf der Straße stehen. So ist das, und es macht mir keine Angst.",
"Soy rico, guapo y un gran jugador. Por eso me tienen envidia. No es mi culpa.":"Ich bin reich, schön und ein großartiger Spieler. Deshalb sind sie neidisch. Nicht meine Schuld.",
"Soy un trabajador del club. Hago lo que me piden y ellos hacen lo suyo. Así de sencillo.":"Ich bin ein Angestellter des Vereins. Ich mache, was sie verlangen, und sie machen ihr Ding. So einfach ist das.",
