"TRIPLETE DE {name}. ¿Alguien tiene un pulso? Yo no. Qué barbaridad.":"DREIERPACK VON {name}. Hat jemand noch Puls? Ich nicht. Wahnsinn.",
"TRIPLETE | {name} firma un hat-trick y lidera al {club} ante el {opp}.":"DREIERPACK | {name} schnürt einen Hattrick und führt {club} gegen {opp} an.",
"Tablas en el duelo entre {me} y {him}: ninguno logra imponerse.":"Remis im Duell zwischen {me} und {him}: Keiner kann sich durchsetzen.",
"Tableta de datos":"Daten-Tablet",
"Tachados: números ocupados en tu club. Si eliges uno ocupado, lo pedirás la próxima temporada.":"Durchgestrichen: in deinem Verein vergebene Nummern. Wählst du eine vergebene, forderst du sie nächste Saison ein.",
