"Tema, avisos y copias":"Design, Erinnerungen und Sicherungen",
"Temas Noche, Día de partido y Retro en Accesibilidad o en el menú.":"Designs Nacht, Spieltag und Retro unter Barrierefreiheit oder im Menü.",
"Temblor de cámara":"Kamerawackeln",
"Temp. de míster":"Trainer-Saisons",
"Temporada":"Saison",
"Temporada 2015/16: el Leicester, que pagaba 5000 a 1 en las casas de apuestas, ganó la Premier League.":"Saison 2015/16: Leicester, bei den Wettanbietern mit einer Quote von 5000:1 gehandelt, gewann die Premier League.",
