"Tensión del momento: estrecha la franja ideal en penaltis y minijuegos.":"Anspannung des Moments: verengt den idealen Bereich bei Elfmetern und Minispielen.",
"Tenías razón: los números mentían y rindes a gran nivel.":"Du hattest recht: Die Zahlen logen, und du spielst auf Topniveau.",
