"Trabajar todo el verano (15 k€)":"Den ganzen Sommer trainieren (15 k€)",
"Trabajas como nadie y el míster empieza a contar contigo.":"Du arbeitest wie kein anderer und der Trainer setzt allmählich auf dich.",
"Trabajo":"Fleiß",
"Trabajo de reflejos cada mañana: +3 en Reflejos y +2 en Paradas.":"Reflextraining jeden Morgen: +3 auf Reflexe und +2 auf Paraden.",
"Trabajo defensivo":"Defensivarbeit",
"Trabajo táctico sin prisas.":"Taktikarbeit ohne Hektik.",
"Trabajo y humildad. No hay más secreto.":"Arbeit und Demut. Mehr Geheimnis gibt es nicht.",
"Trabajo, trabajo y más trabajo. Y mucha suerte en las lesiones. Lo demás son excusas de los otros.":"Arbeit, Arbeit und nochmals Arbeit. Und viel Glück bei den Verletzungen. Der Rest sind Ausreden der anderen.",
"Traduces las instrucciones y poco más. Cumples sin desgastarte.":"Du übersetzt die Anweisungen, mehr nicht. Pflicht erfüllt, ohne dich zu verausgaben.",
"Traer a tu familia una temporada (20 k€)":"Deine Familie für eine Saison holen (20 k€)",
