"Un término medio que deja a todos casi contentos.":"Ein Kompromiss, mit dem alle fast zufrieden sind.",
"Un título es un título. Mañana nos lo habremos olvidado y empezamos a trabajar, que de eso se trata.":"Ein Titel ist ein Titel. Morgen haben wir ihn vergessen und fangen wieder an zu arbeiten, darum geht es.",
"Un título no hace un gran equipo. Que no se confíen.":"Ein Titel macht noch kein großes Team. Bloß nicht abheben.",
"Un título no se pierde en una tarde. Se pierde en una semana de mala cabeza. Y de eso hoy tenemos poco.":"Ein Titel geht nicht an einem Nachmittag verloren. Er geht in einer Woche voller Dummheiten verloren. Und davon haben wir heute wenig.",
