"Un viaje de locos que sale bien: abrazo al bebé y llegas al partido.":"Eine verrückte Reise, die gutgeht: Baby im Arm und rechtzeitig zum Spiel.",
"Un «asesor» te propone meter 150 000 € en una criptomoneda que va a multiplicarse por diez.":"Ein „Berater“ schlägt dir vor, 150.000 € in eine Kryptowährung zu stecken, die sich angeblich verzehnfacht.",
