"Una apuesta enorme que puede salir mal.":"Ein riesiges Wagnis, das schiefgehen kann.",
"Una asistencia y ya lo quieren de MVP. A ver cuando defienda.":"Eine Vorlage und schon wollen sie ihn zum MVP machen. Mal sehen, wann er verteidigt.",
"Una asociación te pide jugar un amistoso benéfico en el parón. El estadio se llenaría y la causa es buena, pero la plantilla ya viene justa.":"Eine Organisation bittet dich, in der Länderspielpause ein Benefizspiel zu bestreiten. Das Stadion wäre voll und der Zweck ist gut, aber der Kader ist schon am Limit.",
