"Una broma se pasa de la raya y un fichaje se siente humillado.":"Ein Streich geht zu weit und ein Neuzugang fühlt sich gedemütigt.",
"Una buena aportación y descanso. Todos contentos.":"Ein ordentlicher Beitrag und Erholung. Alle sind zufrieden.",
"Una cadena te ofrece 200 000 € por dos semanas en un programa de famosos durante tus vacaciones.":"Ein Sender bietet dir 200.000 € für zwei Wochen in einer Promi-Show während deines Urlaubs.",
"Una camiseta chillona":"Ein knallbuntes Trikot",
"Una cantidad muy jugosa. La cantera llora la pérdida.":"Eine sehr saftige Summe. Die Jugend trauert um den Verlust.",
"Una carta por el fútbol en los colegios":"Ein Brief für Fußball an Schulen",
"Una casa de apuestas llama":"Ein Wettanbieter ruft an",
"Una casa de apuestas ofrece mucho dinero por llevar su logo en la camiseta. Parte de la afición y varios jugadores se oponen.":"Ein Wettanbieter bietet viel Geld für sein Logo auf dem Trikot. Ein Teil der Fans und mehrere Spieler sind dagegen.",
"Una casa de apuestas te ofrece mucho dinero por ser su imagen. Varias asociaciones de familias critican a los futbolistas que se prestan a esas campañas.":"Ein Wettanbieter bietet dir viel Geld, um sein Werbegesicht zu werden. Mehrere Familienverbände kritisieren Fußballer, die sich für solche Kampagnen hergeben.",
"Una catástrofe natural ha golpeado a tu país semanas antes de un torneo. La selección debate cómo mostrar su apoyo a las víctimas.":"Eine Naturkatastrophe hat dein Land Wochen vor einem Turnier getroffen. Die Nationalmannschaft berät, wie sie den Opfern ihre Unterstützung zeigen kann.",
"Una charla larga y sincera. Se queda con ganas.":"Ein langes, ehrliches Gespräch. Er bleibt, mit gemischten Gefühlen.",
