"Una editorial te propone publicar tu autobiografía. Un escritor la redactaría por ti, pero quieren anécdotas jugosas del vestuario.":"Ein Verlag schlägt dir vor, deine Autobiografie zu veröffentlichen. Ein Ghostwriter würde sie für dich schreiben, aber sie wollen pikante Anekdoten aus der Kabine.",
"Una empresa te ofrece una plataforma de inteligencia artificial que analiza miles de partidos y te sugiere fichajes. Tus ojeadores temen quedarse sin trabajo.":"Eine Firma bietet dir eine KI-Plattform an, die Tausende Spiele analysiert und dir Transfers vorschlägt. Deine Scouts fürchten um ihre Jobs.",
"Una entrada absurda y te vas con un golpe en el tobillo. El club no está contento.":"Ein sinnloses Foul, und du gehst mit einem geprellten Knöchel vom Platz. Der Verein ist nicht begeistert.",
"Una entrada fea en un rondo y acabáis cara a cara con un compañero. Los demás tienen que separaros.":"Ein hartes Einsteigen im Passspiel und ihr steht Stirn an Stirn mit einem Mitspieler. Die anderen müssen euch trennen.",
