"Una plataforma de directos te ofrece un contrato por emitir tres noches a la semana jugando y charlando con tus seguidores.":"Eine Streaming-Plattform bietet dir einen Vertrag an: dreimal pro Woche abends streamen, zocken und mit deinen Followern quatschen.",
"Una plataforma de streaming quiere grabar tu temporada: cámaras en casa, en el vestuario y en el autobús.":"Eine Streaming-Plattform will deine Saison filmen: Kameras zu Hause, in der Kabine und im Bus.",
"Una plataforma de streaming quiere grabar un documental sobre el club, con cámaras en el vestuario y en tu despacho. Pagan bien.":"Eine Streamingplattform will eine Doku über den Verein drehen, mit Kameras in der Kabine und in deinem Büro. Sie zahlt gut.",
"Una plataforma quiere grabar toda la temporada del club: vestuario, despachos y viajes. Pagan bien y la fama del club se dispararía, pero las cámaras lo ven todo.":"Eine Streamingplattform will die ganze Saison des Vereins filmen: Kabine, Büros und Reisen. Sie zahlt gut und der Verein würde berühmter, aber die Kameras sehen alles.",
"Una plataforma quiere grabar tu temporada: entrenamientos, casa, viajes y vestuario. Te pagan muy bien y tu fama crecería, pero las cámaras lo ven todo.":"Eine Streamingplattform will deine Saison filmen: Training, Zuhause, Reisen und Kabine. Sie zahlt sehr gut und du würdest berühmter, aber die Kameras sehen alles.",
