"🐾 {pet} te echa de menos. Pásate por Yo › Tu mascota.":"🐾 {pet} vermisst dich. Schau mal bei Ich › Dein Haustier vorbei.",
"👋 Gracias por todo, {name}. Te deseamos lo mejor en el {to}. Siempre serás de los nuestros. 💙":"👋 Danke für alles, {name}. Wir wünschen dir das Beste bei {to}. Du wirst immer einer von uns sein. 💙",
"💙 Gracias, afición. Sois el mejor jugador del equipo. ¡Seguimos juntos!":"💙 Danke, Fans. Ihr seid der beste Spieler im Team. Wir bleiben zusammen!",
